'use client'

import * as React from 'react'

import './expand-strip.css'

export type ExpandStripItem = {
    title: string
    description?: React.ReactNode
    /** Any CSS background: colour, gradient or url(). */
    background: string
    href?: string
}

export type ExpandStripProps = {
    items: ExpandStripItem[]
    /** Accessible name for the list. */
    label: string
    className?: string
}

// A row of panels; the one under the pointer or keyboard focus widens to show its
// description. Every title and description is always in the DOM and readable.
const ExpandStrip = ({ items, label, className }: ExpandStripProps) => (
    <ul className={['rad-fx-strip', className].filter(Boolean).join(' ')} aria-label={label}>
        {items.map((item) => {
            const inner = <>
                <span className="rad-fx-strip-title">{item.title}</span>
                {item.description ? <span className="rad-fx-strip-description">{item.description}</span> : null}
            </>
            return <li key={item.title} className="rad-fx-strip-item" style={{ background: item.background }}>
                {item.href
                    ? <a className="rad-fx-strip-body" href={item.href}>{inner}</a>
                    : <div className="rad-fx-strip-body" tabIndex={0}>{inner}</div>}
            </li>
        })}
    </ul>
)

export default ExpandStrip

.rad-fx-strip {
    display: flex;
    gap: 8px;
    height: 280px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.rad-fx-strip-item {
    position: relative;
    flex: 1;
    min-width: 0;
    overflow: hidden;
    border-radius: 16px;
    transition: flex-grow 500ms cubic-bezier(0.3, 0.7, 0.2, 1);
}

.rad-fx-strip-item:hover,
.rad-fx-strip-item:focus-within { flex-grow: 4; }

.rad-fx-strip-body {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    gap: 6px;
    padding: 18px;
    color: #fff;
    text-decoration: none;

    /* A scrim keeps white text readable on any background. */
    background: linear-gradient(to top, rgb(0, 0, 0, 0.75), rgb(0, 0, 0, 0.1) 60%, transparent);
}

.rad-fx-strip-body:focus-visible { outline: 3px solid #fff; outline-offset: -6px; border-radius: 14px; }

.rad-fx-strip-title {
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.rad-fx-strip-description {
    max-height: 0;
    opacity: 0;
    font-size: 0.875rem;
    line-height: 1.4;
    transition: opacity 300ms ease, max-height 400ms ease;
}

.rad-fx-strip-item:hover .rad-fx-strip-description,
.rad-fx-strip-item:focus-within .rad-fx-strip-description { max-height: 6em; opacity: 1; transition-delay: 150ms; }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-strip-item, .rad-fx-strip-description { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-strip-item,
[data-rad-fx-motion='reduce'] .rad-fx-strip-description { transition: none; }
